import unittest
from candidate import remove_vowels

class TestRemoveVowels(unittest.TestCase):
    def test_remove_vowels_empty_string(self):
        self.assertEqual(remove_vowels(""), "")

    def test_remove_vowels_no_vowels(self):
        self.assertEqual(remove_vowels("zbcd"), "zbcd")

    def test_remove_vowels_only_vowels(self):
        self.assertEqual(remove_vowels("aaaaa"), "")

    def test_remove_vowels_mixed_case(self):
        self.assertEqual(remove_vowels("aaBAA"), "B")

    def test_remove_vowels_with_newline(self):
        self.assertEqual(remove_vowels("abcdef\nghijklm"), "bcdf\nghjklm")

    def test_remove_vowels_with_spaces(self):
        self.assertEqual(remove_vowels("hello world"), "hll wrld")

    def test_remove_vowels_with_punctuation(self):
        self.assertEqual(remove_vowels("hello, world!"), "hll, wrld!")

    def test_remove_vowels_with_numbers(self):
        self.assertEqual(remove_vowels("hello123"), "hll123")

    def test_remove_vowels_none_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(None)

    def test_remove_vowels_non_string_input(self):
        with self.assertRaises(TypeError):
            remove_vowels(123)

if __name__ == '__main__':
    unittest.main()
